changeSet.sql:
alter table kb_cronjob add column if not exists domain bigint default 1;
update kb_cronjob set domain=(select id from domain where name = 'kbee');
create index if not exists kb_cronjob_domain_idx on kb_cronjob(domain, lower(name));

delete from po_viewbk;
delete from po_viewbkblock;
delete from po_block;
delete from po_area;
delete from po_page;
delete from po_site;
delete from po_site_favorites;
delete from po_site_favorites_list;
delete from po_siteuserrights;
delete from po_siteuser;
delete from po_site_securityrule;
delete from po_portalobject;

CREATE TABLE if not exists po_page_section
	(
	    po_id bigint NOT NULL,
	    page_id bigint,
	    page_section_type integer,
	    orden integer,
	    full_width_canvas boolean,
	    page_section_class character varying(128) COLLATE pg_catalog."default",
	    custom_values text COLLATE pg_catalog."default",
	    CONSTRAINT po_page_section_pkey PRIMARY KEY (po_id),
	    CONSTRAINT po_page_section_page_fk FOREIGN KEY (page_id) REFERENCES po_page(po_id) ON DELETE CASCADE
	);

	alter table po_area drop column if exists parent_area_id;
	ALTER TABLE po_area drop column if exists page_id;
	ALTER TABLE po_area add column if not exists page_section_id bigint references po_page_section REFERENCES po_page (po_id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE;

insert into kb_model_section (id, name, contenttemplate_id, position)  select nextval('domainid_sequence'), 'Attributes', KT.id,  0 from kb_contenttemplate KT where KT.id not in (select contenttemplate_id from kb_model_section group by  contenttemplate_id);
update kb_classifiertemplate K set section_id = (select id from kb_model_section where contenttemplate_id = K.contenttemplate_id limit 1) where K.section_id is null;
update kb_attributetemplate K set section_id = (select id from kb_model_section where contenttemplate_id = (select contenttemplate_id from kb_attribute B where B.id=K.attribute_id) limit 1) where K.section_id is null;

update Kb_ClassifierTemplate   set multiplicity=1 where multiplicity is null;
update Kb_ClassifierTemplate set  accessibility=2 where  accessibility is null;
update KB_AttributeTemplate    set multiplicity=1 where multiplicity is null;
update Kb_Ds_Element_Template  set multiplicity=1 where multiplicity is null;

        update dataset set alias = lower(replace(name,' ', '')) where alias is null;
		update kb_classifier set alias = lower(replace(name,' ', '')) where alias is null;
		update kb_attribute set alias = lower(replace(name,' ', '')) where alias is null;
